package com.example.domain.model.i18n

internal object DuaMr2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_muawwidhat" to DuaText("तीन कुल (मुअव्विजात)", "(सूरह इखलास) सांगा: तो अल्लाह एक आहे. अल्लाह निरपेक्ष आहे. त्याने कोणाला जन्म दिला नाही आणि तो कोणापासून जन्मला नाही. आणि त्याच्या तोडीचा कोणी नाही.\n\n(सूरह फलक) सांगा: मी पहाटेच्या रबचा आश्रय मागतो, त्याने निर्माण केलेल्या प्रत्येक गोष्टीच्या वाईटापासून, अंधाऱ्या रात्रीच्या वाईटापासून जेव्हा ती पसरते, गाठींवर फुंकणाऱ्यांच्या वाईटापासून, आणि मत्सर करणाऱ्याच्या वाईटापासून जेव्हा तो मत्सर करतो.\n\n(सूरह नास) सांगा: मी माणसांच्या रबचा आश्रय मागतो, माणसांच्या राजाचा, माणसांच्या उपास्याचा, त्या वसवसा घालणाऱ्याच्या वाईटापासून जो (अल्लाहचा जिक्र ऐकून) मागे हटतो, जो लोकांच्या हृदयात वसवसा घालतो, मग तो जिन्नांपैकी असो वा माणसांपैकी.", "सकाळ-संध्याकाळ तिन्ही सूरह तीन-तीन वेळा, आणि झोपण्यापूर्वी हातांवर फुंकून शरीरावर फिरवणे.", "सकाळ-संध्याकाळ तीन वेळा पठण करणे प्रत्येक गोष्टीपासून पुरेसे होते."),
        "dua_sabr" to DuaText("संयम आणि दृढतेसाठी", "हे आमच्या रब! आमच्यावर संयम ओत, आमचे पाय दृढ कर आणि काफिर लोकांविरुद्ध आम्हाला मदत कर.", "अडचणीच्या आणि सामन्याच्या वेळी.", "तालूतच्या सैन्याची दुआ."),
        "dua_rabbana_innana_amanna" to DuaText("क्षमा आणि आगीपासून संरक्षण", "हे आमच्या रब! आम्ही ईमान आणले, म्हणून आमची पापे माफ कर आणि आम्हाला आगीच्या शिक्षेपासून वाचव.", "कुरआनी दुआ.", "ईशपरायणांच्या गुणांमध्ये वर्णन केलेली दुआ."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("आमच्या कामात मार्गदर्शन (असहाब-ए-कहफ)", "हे आमच्या रब! आम्हाला तुझ्याकडून कृपा दे आणि आमच्या कामात आमच्यासाठी योग्य मार्ग सुलभ कर.", "गुहेतील तरुणांची दुआ.", "निर्णय आणि कठीण परिस्थितीत मार्गदर्शन."),
        "dua_musa_faqir" to DuaText("रोजीसाठी मूसा (अ.) यांची दुआ", "हे माझ्या रब! तू माझ्यावर जे काही भले उतरवशील, मी त्याचा गरजू आहे.", "रोजी आणि भल्याची मागणी — मदयनमध्ये मूसा (अ.) यांची दुआ.", "या दुआनंतर अल्लाहने मूसा (अ.) यांना घर, उपजीविका आणि पत्नी दिली."),
        "dua_ayyub" to DuaText("आजारपणात अय्यूब (अ.) यांची दुआ", "(हे माझ्या रब!) मला त्रास झाला आहे आणि तू सर्व दयाळूंपेक्षा अधिक दयाळू आहेस.", "आजारपण आणि त्रासात.", "अल्लाहने अय्यूब (अ.) यांचा त्रास दूर केला."),
        "dua_husn_khatimah" to DuaText("मुस्लिम म्हणून मृत्यू (यूसुफ अ.)", "हे आकाश व पृथ्वीच्या निर्मात्या! तूच दुनिया आणि आखिरतमध्ये माझा संरक्षक आहेस. मला मुस्लिम स्थितीत मृत्यू दे आणि सदाचारी लोकांशी जोड.", "चांगल्या शेवटाची दुआ.", "यूसुफ (अ.) यांची दुआ."),
        "dua_shaitan_hamazat" to DuaText("शैतानांच्या वसवशांपासून आश्रय", "हे माझ्या रब! मी शैतानांच्या वसवशांपासून तुझा आश्रय मागतो, आणि हे माझ्या रब! ते माझ्याजवळ येण्यापासूनही तुझा आश्रय मागतो.", "शैतानी वसवशांपासून आश्रय.", "कुरआनी आश्रयाची दुआ."),
        "dua_bad_character" to DuaText("वाईट चारित्र्यापासून आश्रय", "हे अल्लाह! मी वाईट चारित्र्य, वाईट कर्मे आणि वाईट इच्छांपासून तुझा आश्रय मागतो.", "वाईट चारित्र्य, कर्मे आणि इच्छांपासून आश्रय.", "नबी ﷺ यांची आश्रयाची दुआ."),
        "dua_zawal_nimah" to DuaText("कृपा हिरावण्यापासून आश्रय", "हे अल्लाह! मी तुझा आश्रय मागतो तुझी कृपा नाहीशी होण्यापासून, तू दिलेली सुरक्षितता बदलण्यापासून, तुझ्या अचानक शिक्षेपासून आणि तुझ्या प्रत्येक नाराजीपासून.", "कृपा हिरावणे आणि अचानक संकटापासून आश्रय.", "नबी ﷺ यांची दुआ."),
        "dua_useless_knowledge" to DuaText("निरुपयोगी ज्ञानापासून आश्रय", "हे अल्लाह! मी तुझा आश्रय मागतो अशा ज्ञानापासून जे उपयोगी नाही, अशा हृदयापासून जे भीत नाही, अशा मनापासून जे तृप्त होत नाही, आणि अशा दुआपासून जी कबूल होत नाही.", "निरुपयोगी ज्ञान आणि निर्भय हृदयापासून आश्रय.", "नबी ﷺ यांची आश्रयाची दुआ."),
        "dua_beneficial_knowledge" to DuaText("उपयुक्त ज्ञान आणि हलाल रोजी", "हे अल्लाह! मी तुझ्याकडे उपयुक्त ज्ञान, पवित्र रोजी आणि स्वीकारले जाणारे कर्म मागतो.", "फज्रच्या नमाजनंतर.", "नबी ﷺ फज्रच्या सलामनंतर ही दुआ करत."),
        "dua_leprosy_diseases" to DuaText("गंभीर आजारांपासून आश्रय", "हे अल्लाह! मी तुझा आश्रय मागतो कोड, वेडेपणा, कुष्ठरोग आणि सर्व वाईट आजारांपासून.", "वाईट आजारांपासून संरक्षण.", "आरोग्य रक्षणाची मसनून दुआ."),
        "dua_fear_people" to DuaText("शत्रू किंवा अत्याचाऱ्याची भीती", "हे अल्लाह! आम्ही तुला त्यांच्यासमोर ठेवतो आणि त्यांच्या वाईटापासून तुझा आश्रय मागतो.", "एखाद्या समूहाच्या किंवा व्यक्तीच्या वाईटाची भीती असल्यास.", "नबी ﷺ एखाद्या समूहापासून धोका वाटल्यास हे म्हणत."),
        "dua_shirk_protection" to DuaText("छुप्या शिर्कपासून संरक्षण", "हे अल्लाह! मी तुझा आश्रय मागतो जाणूनबुजून तुझ्यासोबत शिर्क करण्यापासून, आणि जे नकळत होते त्याची क्षमा मागतो.", "दिखावा आणि छुप्या शिर्कपासून वाचण्यासाठी.", "छुपा शिर्क मुंगीच्या चालीपेक्षाही सूक्ष्म आहे."),
        "dua_rain" to DuaText("पाऊस पडताना", "हे अल्लाह! लाभदायक पाऊस पाड.", "पाऊस पडताना.", "पाऊस दुआ कबूल होण्याची वेळ आहे."),
        "dua_after_rain" to DuaText("पावसानंतर", "अल्लाहच्या कृपेने आणि दयेने आमच्यावर पाऊस पडला.", "पावसानंतर.", "हे म्हणणारा अल्लाहवर ईमान ठेवणारा आहे."),
        "dua_istisqa" to DuaText("पावसाची प्रार्थना (इस्तिस्का)", "हे अल्लाह! आमच्यावर पाऊस पाड (तीन वेळा).", "पाऊस न पडल्यास.", "नबी ﷺ यांनी जुम्माच्या खुत्ब्यात ही दुआ केली आणि पाऊस पडला."),
        "dua_heavy_rain" to DuaText("अतिवृष्टी", "हे अल्लाह! आमच्या आजूबाजूला (पाड), आमच्यावर नाही.", "पाऊस जास्त झाल्यास.", "नबी ﷺ यांच्या दुआने ढग दूर झाले."),
        "dua_wind" to DuaText("जोराचा वारा वाहताना", "हे अल्लाह! मी तुझ्याकडे याचे भले, यात जे आहे त्याचे भले आणि ज्यासोबत हा पाठवला गेला त्याचे भले मागतो, आणि याच्या वाईटापासून, यात जे आहे त्याच्या वाईटापासून आणि ज्यासोबत पाठवला गेला त्याच्या वाईटापासून तुझा आश्रय मागतो.", "जोराचा वारा/वादळ वाहताना.", "नबी ﷺ वादळाच्या वेळी ही दुआ करत."),
        "dua_thunder" to DuaText("गडगडाट ऐकून", "पवित्र आहे तो ज्याची स्तुतीसह गडगडाट तस्बीह करतो आणि फरिश्तेही त्याच्या भीतीने.", "गडगडाट ऐकून — अब्दुल्लाह बिन जुबैर (र.) यांची प्रथा.", "सूरह रअद (१३:१३) मधून घेतलेले."),
        "dua_new_moon" to DuaText("नवा चंद्र पाहून", "हे अल्लाह! हा चंद्र आमच्यावर बरकत, ईमान, सुरक्षितता आणि इस्लामसह उदित कर. (हे चंद्रा!) माझा आणि तुझा रब अल्लाह आहे.", "नवा चंद्र पाहून.", "प्रत्येक नव्या महिन्याची मसनून दुआ."),
        "dua_janaza_adult" to DuaText("जनाजा नमाज (प्रौढ)", "हे अल्लाह! आमचे जिवंत व मृत, उपस्थित व अनुपस्थित, लहान व मोठे, पुरुष व स्त्रिया सर्वांना क्षमा कर. हे अल्लाह! आमच्यापैकी ज्याला जिवंत ठेवशील त्याला इस्लामवर जिवंत ठेव, आणि ज्याला मृत्यू देशील त्याला ईमानवर मृत्यू दे.", "जनाजा नमाजच्या तिसऱ्या तकबीरनंतर.", "प्रौढ मृताची मसनून दुआ."),
        "dua_janaza_child" to DuaText("जनाजा नमाज (मूल)", "हे अल्लाह! याला आमच्यासाठी पुढे जाणारा (यजमान) बनव, याला आमच्यासाठी मोबदला आणि ठेवा बनव, आणि याला आमच्यासाठी शिफारस करणारा आणि ज्याची शिफारस स्वीकारली जाते असा बनव.", "अल्पवयीन मुलाच्या जनाजा नमाजमध्ये (मुलगी असल्यास 'इज्अल्हा').", "हनफींमध्ये प्रचलित मसनून दुआ."),
        "dua_mayyit_awf" to DuaText("मृतासाठी सविस्तर दुआ", "हे अल्लाह! याला क्षमा कर, याच्यावर दया कर, याला सुरक्षितता दे, याला माफ कर, याचे आदरातिथ्य सन्मानपूर्वक कर, याची कबर विस्तृत कर, याला पाणी, बर्फ आणि गारांनी धुऊन काढ, आणि याला पापांपासून असे स्वच्छ कर जसे पांढरा कपडा मळापासून स्वच्छ केला जातो.", "जनाजामध्ये किंवा मृतासाठी.", "औफ बिन मालिक (र.) यांनी इच्छा केली की हा मृत मी असतो तर."),
        "dua_visiting_graves" to DuaText("कबरस्तानची भेट", "हे मोमिन आणि मुस्लिम घरवाल्यांनो, तुमच्यावर शांती असो. आम्हीही इन शा अल्लाह तुम्हाला भेटणार आहोत. मी अल्लाहकडे आमच्यासाठी आणि तुमच्यासाठी सुरक्षितता मागतो.", "कबरस्तानात प्रवेश करताना.", "कबरींची भेट मृत्यू आणि आखिरतची आठवण करून देते."),
        "dua_closing_eyes" to DuaText("मृताचे डोळे बंद करताना", "हे अल्लाह! (अमुक) याला क्षमा कर, मार्गदर्शित लोकांत याचा दर्जा उंच कर, याच्या मागे राहिलेल्यांमध्ये तू याचा उत्तराधिकारी हो, हे सर्व जगांच्या रब! आम्हाला आणि याला क्षमा कर, याची कबर विस्तृत कर आणि त्यात प्रकाश कर.", "मृताचे डोळे बंद करताना (नाव घेऊन).", "नबी ﷺ यांनी अबू सलमा (र.) यांच्यासाठी ही दुआ केली."),
        "dua_condolence" to DuaText("सांत्वन (ताजियत)", "निश्चितच अल्लाहचेच होते जे त्याने घेतले आणि त्याचेच आहे जे त्याने दिले, आणि त्याच्याकडे प्रत्येक गोष्टीची निश्चित वेळ आहे, म्हणून संयम ठेवा आणि पुण्याची आशा ठेवा.", "कोणाच्या निधनावर कुटुंबाचे सांत्वन.", "नबी ﷺ यांनी आपल्या कन्येला हा संदेश पाठवला."),
        "dua_placing_in_grave" to DuaText("मृताला कबरीत ठेवणे", "अल्लाहच्या नावाने आणि रसूलुल्लाह ﷺ यांच्या मिल्लतवर.", "मृताला कबरीत उतरवताना.", "दफनाची मसनून दुआ."),
        "dua_sneezing" to DuaText("शिंक आल्यावर", "सर्व स्तुती अल्लाहसाठी. — अल्लाह तुझ्यावर दया करो. — अल्लाह तुला मार्गदर्शन देवो आणि तुझी स्थिती सुधारो.", "शिंक आल्यावर; ऐकणारा 'यरहमुकल्लाह' म्हणेल, मग शिंकणारा उत्तर देईल.", "मुस्लिमाचा मुस्लिमावरील हक्कांपैकी एक."),
        "dua_toilet_enter" to DuaText("शौचालयात प्रवेश", "अल्लाहच्या नावाने. हे अल्लाह! मी अपवित्र नर व मादी जिन्नांपासून तुझा आश्रय मागतो.", "डावा पाय ठेवून शौचालयात प्रवेश करण्यापूर्वी.", "बिस्मिल्लाह जिन्न आणि माणसाच्या गुप्तांगांमध्ये पडदा बनते."),
        "dua_toilet_exit" to DuaText("शौचालयातून बाहेर पडताना", "(हे अल्लाह!) मी तुझी क्षमा मागतो.", "उजवा पाय बाहेर टाकून शौचालयातून बाहेर पडताना.", "नबी ﷺ शौचालयातून बाहेर पडून हे म्हणत."),
        "dua_thanking" to DuaText("कोणाचे आभार", "अल्लाह तुला उत्तम मोबदला देवो.", "कोणी उपकार केल्यास.", "ज्याने हे म्हटले त्याने स्तुतीचा हक्क पूर्ण केला."),
        "dua_love_for_allah" to DuaText("कोणी म्हणाले 'मी तुझ्यावर अल्लाहसाठी प्रेम करतो'", "ज्याच्यासाठी तू माझ्यावर प्रेम करतोस तो (अल्लाह) तुझ्यावर प्रेम करो.", "कोणी म्हणाले 'मी तुझ्यावर अल्लाहसाठी प्रेम करतो'.", "अल्लाहसाठी प्रेमाचे मसनून उत्तर."),
        "dua_seeing_muslim_smile" to DuaText("सलाम", "तुझ्यावर शांती, अल्लाहची कृपा आणि त्याच्या बरकती असोत.", "मुस्लिमाला भेटताना.", "पूर्ण सलाम केल्यास तीस पुण्ये मिळतात."),
        "dua_dressing" to DuaText("कपडे घालणे", "सर्व स्तुती अल्लाहसाठी ज्याने मला हा कपडा घातला आणि माझ्या कोणत्याही शक्ती व सामर्थ्याशिवाय दिला.", "कपडे घालताना.", "मागील पापांच्या क्षमेची शुभवार्ता."),
        "dua_rooster_donkey" to DuaText("कोंबडा किंवा गाढवाचा आवाज ऐकून", "हे अल्लाह! मी तुझी कृपा मागतो (कोंबडा). — मी धिक्कारलेल्या शैतानापासून अल्लाहचा आश्रय मागतो (गाढव).", "कोंबड्याच्या आवाजावर अल्लाहची कृपा मागा, गाढवाच्या ओरडण्यावर शैतानापासून आश्रय.", "कोंबडा फरिश्ता पाहतो आणि गाढव शैतान."),
        "dua_something_liked" to DuaText("आवडती गोष्ट पाहून (दृष्टीपासून बचाव)", "जे अल्लाहने इच्छिले. हे अल्लाह! यात बरकत दे.", "कोणाची चांगली गोष्ट पाहून बरकतीची दुआ द्या.", "बरकतीची दुआ दिल्याने दृष्ट लागत नाही."),
        "dua_sell_buy_debt_repaid" to DuaText("कर्ज परत करताना", "अल्लाह तुझ्या कुटुंबात आणि संपत्तीत बरकत देवो.", "कर्ज परत करताना कर्ज देणाऱ्यासाठी.", "कर्जाचा मोबदला म्हणजे आभार आणि परतफेड."),
        "dua_talbiyah" to DuaText("तलबिया", "मी हजर आहे, हे अल्लाह मी हजर आहे. मी हजर आहे, तुला कोणी भागीदार नाही, मी हजर आहे. निश्चितच सर्व स्तुती, कृपा आणि राज्य तुझेच आहे, तुला कोणी भागीदार नाही.", "इहराम बांधल्यानंतर मोठ्या आवाजात.", "हज आणि उमराचे प्रतीक."),
        "dua_yamani_hajar" to DuaText("रुक्न-ए-यमानी आणि हजर-ए-अस्वद दरम्यान", "हे आमच्या रब! आम्हाला दुनियेतही भले दे आणि आखिरतमध्येही भले दे, आणि आम्हाला आगीच्या शिक्षेपासून वाचव.", "तवाफमध्ये रुक्न-ए-यमानी आणि हजर-ए-अस्वद दरम्यान.", "नबी ﷺ तवाफमध्ये या ठिकाणी हे पठण करत."),
        "dua_safa_marwa" to DuaText("सफा आणि मरवावर", "अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही, राज्य आणि स्तुती त्याचीच आणि तो प्रत्येक गोष्टीवर समर्थ आहे. अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याने आपले वचन पूर्ण केले, आपल्या दासाला मदत केली आणि एकट्याने सर्व सैन्यांचा पराभव केला.", "सफावर चढून किब्लाकडे तोंड करून (तीन वेळा).", "सफा आणि मरवावर नबी ﷺ यांचा जिक्र."),
        "dua_arafah" to DuaText("अरफाच्या दिवसाची सर्वोत्तम दुआ", "अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही, राज्य आणि स्तुती त्याचीच आणि तो प्रत्येक गोष्टीवर समर्थ आहे.", "अरफाचा दिवस — सर्वोत्तम दुआ.", "सर्वोत्तम दुआ अरफाच्या दिवसाची दुआ आहे, आणि सर्वोत्तम वाक्य हे आहे."),
        "dua_takbeer_tashreeq" to DuaText("तकबीर-ए-तशरीक", "अल्लाह सर्वात महान आहे, अल्लाह सर्वात महान आहे. अल्लाहशिवाय कोणी उपास्य नाही. अल्लाह सर्वात महान आहे, अल्लाह सर्वात महान आहे, आणि सर्व स्तुती अल्लाहसाठीच आहे.", "९ जिल्हिज्जा फज्रपासून १३ जिल्हिज्जा अस्रपर्यंत प्रत्येक फर्ज नमाजनंतर.", "अली आणि इब्न मसऊद (र.) यांच्याकडून वर्णित — हनफींमध्ये वाजिब."),
        "dua_zamzam" to DuaText("झमझम पिताना", "हे अल्लाह! मी तुझ्याकडे उपयुक्त ज्ञान, विपुल रोजी आणि प्रत्येक आजारापासून आरोग्य मागतो.", "झमझम पिताना जी नियत असेल तिची दुआ करा.", "झमझम ज्या नियतीने प्याले जाते त्यासाठीच आहे (इब्न माजा ३०६२)."),
        "dua_q_ma_khalaqta_batila" to DuaText("सृष्टीवर चिंतन", "हे आमच्या रब! तू हे सर्व व्यर्थ निर्माण केले नाहीस, तू पवित्र आहेस, म्हणून आम्हाला आगीच्या शिक्षेपासून वाचव.", "आकाश व पृथ्वीच्या सृष्टीवर चिंतन करणाऱ्यांची दुआ.", "बुद्धिमानांची (उलुल अल्बाब) दुआ."),
        "dua_q_sami_na_munadiyan" to DuaText("आम्ही ईमानच्या हाक देणाऱ्याला ऐकले", "हे आमच्या रब! आम्ही एका हाक देणाऱ्याला ईमानकडे बोलावताना ऐकले की आपल्या रबवर ईमान आणा, म्हणून आम्ही ईमान आणले. हे आमच्या रब! आमची पापे क्षमा कर, आमच्या वाईट गोष्टी आमच्यापासून दूर कर आणि आम्हाला सदाचारी लोकांसोबत मृत्यू दे.", "ईमान आणि सदाचारी लोकांसोबत मृत्यूची दुआ.", "क्षमा आणि चांगल्या शेवटाची दुआ."),
        "dua_q_atina_ma_waadtana" to DuaText("जे वचन दिलेस ते दे", "हे आमच्या रब! तू तुझ्या रसूलांद्वारे जे वचन दिलेस ते आम्हाला दे, आणि कयामतच्या दिवशी आम्हाला अपमानित करू नकोस, निश्चितच तू वचनभंग करत नाहीस.", "कयामतच्या अपमानापासून आश्रय.", "आखिरतमध्ये सन्मानाची मागणी."),
        "dua_q_israfana" to DuaText("आमचे अतिरेक क्षमा कर", "हे आमच्या रब! आमची पापे आणि आमच्या कामातील अतिरेक क्षमा कर, आमचे पाय दृढ कर आणि काफिर लोकांविरुद्ध आम्हाला मदत कर.", "पूर्वीच्या नबींच्या साथीदारांची दुआ.", "दृढता आणि क्षमेची दुआ."),
        "dua_q_jamiun_nas" to DuaText("तू लोकांना एकत्र करणारा आहेस", "हे आमच्या रब! निश्चितच तू लोकांना अशा दिवशी एकत्र करणार आहेस ज्यात कोणतीही शंका नाही. निश्चितच अल्लाह वचनभंग करत नाही.", "कयामतवरील विश्वासाची कबुली.", "ज्ञानात दृढ असलेल्यांची दुआ."),
        "dua_q_maash_shahidin" to DuaText("आम्हाला साक्षीदारांत लिही", "हे आमच्या रब! आम्ही ईमान आणले, म्हणून आम्हाला साक्ष देणाऱ्यांसोबत लिही.", "सत्य ओळखून ईमान आणणाऱ्यांची दुआ.", "ईमानच्या स्वीकृतीची दुआ."),
        "dua_q_la_tajalna_zalimin" to DuaText("अत्याचाऱ्यांसोबत ठेवू नकोस", "हे आमच्या रब! आम्हाला अत्याचारी लोकांसोबत ठेवू नकोस.", "अअराफवाल्यांची दुआ.", "अत्याचाऱ्यांच्या परिणामापासून आश्रय."),
        "dua_q_tawaffana_muslimin" to DuaText("संयम आणि मुस्लिम म्हणून मृत्यू", "हे आमच्या रब! आमच्यावर संयम ओत आणि आम्हाला मुस्लिम स्थितीत मृत्यू दे.", "फिरऔनच्या जादूगारांनी ईमान आणल्यावरची दुआ.", "परीक्षेत संयम आणि ईमानवर शेवट."),
        "dua_q_la_tajalna_fitnah" to DuaText("अत्याचाऱ्यांसाठी परीक्षा बनवू नकोस", "आम्ही अल्लाहवर भरवसा ठेवला. हे आमच्या रब! आम्हाला अत्याचारी लोकांसाठी परीक्षा बनवू नकोस, आणि तुझ्या कृपेने आम्हाला काफिर लोकांपासून सुटका दे.", "मूसा (अ.) यांच्या लोकांची दुआ.", "अत्याचार आणि अत्याचाऱ्यांपासून सुटकेची दुआ."),
        "dua_q_nuh_ma_laysa_li" to DuaText("क्षमेसाठी नूह (अ.) यांची दुआ", "हे माझ्या रब! मी तुझा आश्रय मागतो की तुझ्याकडे असे काही मागू ज्याचे मला ज्ञान नाही. जर तू मला क्षमा केली नाहीस आणि माझ्यावर दया केली नाहीस तर मी नुकसान सोसणाऱ्यांपैकी होईन.", "नूह (अ.) यांची तौबाची दुआ.", "आदराने दुआ करण्याची शिकवण."),
        "dua_q_mudkhala_sidq" to DuaText("सत्यासह प्रवेश आणि निर्गमन", "हे माझ्या रब! मला सत्यासह प्रवेश दे आणि सत्यासह बाहेर काढ, आणि तुझ्याकडून मला मदत करणारे सामर्थ्य दे.", "एखादे नवे काम, घर किंवा ठिकाणी प्रवेश करण्यापूर्वी.", "हिजरतच्या वेळी नबी ﷺ यांना शिकवलेली दुआ."),
        "dua_q_la_tadharni_fardan" to DuaText("मला एकटे सोडू नकोस (जकरिया अ.)", "हे माझ्या रब! मला एकटे सोडू नकोस, आणि तू सर्वोत्तम वारस आहेस.", "संतती मागण्यासाठी.", "या दुआवर अल्लाहने यह्या (अ.) दिले."),
        "dua_q_munzalan_mubarakan" to DuaText("बरकतयुक्त ठिकाणी उतरव", "हे माझ्या रब! मला बरकतयुक्त ठिकाणी उतरव, आणि तू सर्वोत्तम उतरवणारा आहेस.", "नवीन घरात राहायला जाताना किंवा कुठे उतरताना — नूह (अ.) यांची दुआ.", "नवीन ठिकाणी बरकतीची दुआ."),
        "dua_q_amanna_faghfir" to DuaText("आम्ही ईमान आणले, आम्हाला क्षमा कर", "हे आमच्या रब! आम्ही ईमान आणले, म्हणून आम्हाला क्षमा कर आणि आमच्यावर दया कर, आणि तू सर्वोत्तम दया करणारा आहेस.", "अल्लाहच्या सदाचारी दासांची दुआ.", "क्षमा आणि कृपेची व्यापक दुआ."),
        "dua_q_isrif_jahannam" to DuaText("जहन्नमची शिक्षा दूर कर", "हे आमच्या रब! जहन्नमची शिक्षा आमच्यापासून दूर कर, निश्चितच तिची शिक्षा चिकटून राहणारी आहे. निश्चितच ते वाईट ठिकाण आणि वाईट निवास आहे.", "रहमानच्या दासांची दुआ.", "जहन्नमपासून आश्रयाची कुरआनी दुआ."),
        "dua_q_hab_li_hukman" to DuaText("शहाणपण आणि जन्नत (इब्राहीम अ.)", "हे माझ्या रब! मला शहाणपण दे आणि सदाचारी लोकांशी जोड, नंतरच्या पिढ्यांमध्ये माझे चांगले स्मरण चालू ठेव, आणि मला आनंदमय जन्नतच्या वारसांपैकी बनव.", "शहाणपण, सदाचारींची संगत आणि जन्नतची मागणी.", "इब्राहीम (अ.) यांची व्यापक दुआ."),
        "dua_q_lut_najjini_ahli" to DuaText("माझ्या कुटुंबाला वाचव (लूत अ.)", "हे माझ्या रब! मला आणि माझ्या कुटुंबाला त्यांच्या कृत्यांच्या (परिणामापासून) सुटका दे.", "वाईट वातावरणापासून कुटुंबाचे संरक्षण.", "वाईटापासून कुटुंबाचे संरक्षण."),
        "dua_q_sulaiman_awzini" to DuaText("कृतज्ञतेसाठी सुलैमान (अ.) यांची दुआ", "हे माझ्या रब! मला सामर्थ्य दे की मी तुझ्या त्या कृपेचे आभार मानू जी तू माझ्यावर आणि माझ्या आई-वडिलांवर केलीस, आणि असे सत्कर्म करू जे तुला आवडेल, आणि तुझ्या कृपेने मला तुझ्या सदाचारी दासांत सामील कर.", "कृपेबद्दल कृतज्ञतेचे सामर्थ्य.", "सुलैमान (अ.) यांची कृतज्ञतेची दुआ."),
        "dua_q_musa_zalamtu" to DuaText("मी स्वतःवर अन्याय केला (मूसा अ.)", "हे माझ्या रब! मी स्वतःवर अन्याय केला, म्हणून मला क्षमा कर.", "चूक झाल्यावर लगेच तौबा.", "अल्लाहने मूसा (अ.) यांना क्षमा केली."),
        "dua_q_musa_najjini" to DuaText("अत्याचाऱ्यांपासून वाचव (मूसा अ.)", "हे माझ्या रब! मला अत्याचारी लोकांपासून सुटका दे.", "अत्याचाऱ्यांच्या भीतीत.", "मिस्रमधून निघताना मूसा (अ.) यांची दुआ."),
        "dua_q_lut_unsurni" to DuaText("उपद्रव्यांविरुद्ध मदत (लूत अ.)", "हे माझ्या रब! उपद्रव करणाऱ्या लोकांविरुद्ध मला मदत कर.", "उपद्रव करणाऱ्यांच्या विरुद्ध मदत.", "सत्यावर दृढ राहणाऱ्यांची दुआ."),
        "dua_q_hab_li_salihin" to DuaText("सदाचारी संततीसाठी इब्राहीम (अ.) यांची दुआ", "हे माझ्या रब! मला सदाचारी (संतती) दे.", "सदाचारी संततीची मागणी.", "या दुआवर इस्माईल (अ.) मिळाले."),
        "dua_q_wasita_kulla_shay" to DuaText("अर्श उचलणाऱ्या फरिश्त्यांची दुआ", "हे आमच्या रब! तुझी कृपा आणि ज्ञान प्रत्येक गोष्टीला व्यापून आहे, म्हणून ज्यांनी तौबा केली आणि तुझ्या मार्गाचे अनुसरण केले त्यांना क्षमा कर, आणि त्यांना जहन्नमच्या शिक्षेपासून वाचव.", "अर्श उचलणारे फरिश्ते मोमिनांसाठी ही दुआ करतात.", "फरिश्त्यांच्या दुआत सामील होण्याच्या नियतीने."),
        "dua_q_ikhwanina" to DuaText("आमच्या आधीच्या बांधवांसाठी", "हे आमच्या रब! आम्हाला आणि आमच्या त्या बांधवांना क्षमा कर जे आमच्या आधी ईमान आणले, आणि आमच्या हृदयांत ईमानवाल्यांबद्दल कोणताही द्वेष ठेवू नकोस. हे आमच्या रब! निश्चितच तू अत्यंत स्नेहशील, दयाळू आहेस.", "पूर्वीच्या मोमिनांसाठी आणि हृदयाच्या शुद्धतेची दुआ.", "सहाबा (र.) आणि पूर्वीच्या मोमिनांसाठी दुआ."),
        "dua_q_alayka_tawakkalna" to DuaText("तुझ्यावरच आम्ही भरवसा ठेवला (इब्राहीम अ.)", "हे आमच्या रब! आम्ही तुझ्यावर भरवसा ठेवला, तुझ्याकडे वळलो आणि तुझ्याकडेच परत जायचे आहे. हे आमच्या रब! आम्हाला काफिरांसाठी परीक्षा बनवू नकोस आणि आम्हाला क्षमा कर. हे आमच्या रब! निश्चितच तू प्रबळ, शहाणा आहेस.", "इब्राहीम (अ.) आणि त्यांच्या साथीदारांची दुआ.", "तवक्कुल आणि परतण्याची दुआ."),
        "dua_q_atmim_nurana" to DuaText("आमचा प्रकाश पूर्ण कर", "हे आमच्या रब! आमच्यासाठी आमचा प्रकाश पूर्ण कर आणि आम्हाला क्षमा कर, निश्चितच तू प्रत्येक गोष्टीवर समर्थ आहेस.", "कयामतच्या दिवशी मोमिनांची दुआ.", "पुल-सिरातवर प्रकाशाची मागणी."),
        "dua_q_asiya_baytan" to DuaText("जन्नतमध्ये घर (आसिया)", "हे माझ्या रब! माझ्यासाठी तुझ्याजवळ जन्नतमध्ये घर बनव, आणि मला फिरऔन आणि त्याच्या कृत्यांपासून सुटका दे, आणि अत्याचारी लोकांपासून सुटका दे.", "फिरऔनच्या पत्नी आसिया यांची दुआ.", "अल्लाहने त्यांना मोमिनांसाठी उदाहरण बनवले."),
        "dua_adhan_response" to DuaText("अजानला उत्तर", "अल्लाहशिवाय कोणतीही शक्ती नाही आणि कोणतेही सामर्थ्य नाही.", "मुअज्जिन जे म्हणतो तेच पुन्हा म्हणा; 'हय्या अलस्सलाह' आणि 'हय्या अलल फलाह' वर हे म्हणा.", "मनापासून उत्तर देणारा जन्नतमध्ये प्रवेश करेल."),
        "dua_adhan_shahadah" to DuaText("मुअज्जिनच्या शहादतनंतर", "आणि मीही साक्ष देतो की अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही, आणि मुहम्मद ﷺ त्याचे दास आणि रसूल आहेत. मी अल्लाहला रब, मुहम्मद ﷺ यांना रसूल आणि इस्लामला दीन म्हणून स्वीकारून समाधानी आहे.", "मुअज्जिनची शहादतैन ऐकून.", "त्याची पापे माफ होतात."),
        "dua_istiftah_baid" to DuaText("प्रारंभिक दुआ: मला पापांपासून दूर कर", "हे अल्लाह! माझ्या आणि माझ्या पापांमध्ये इतके अंतर कर जितके तू पूर्व आणि पश्चिमेत केलेस. हे अल्लाह! मला पापांपासून असे स्वच्छ कर जसे पांढरा कपडा मळापासून स्वच्छ केला जातो. हे अल्लाह! माझी पापे पाणी, बर्फ आणि गारांनी धुऊन टाक.", "तकबीर-ए-तहरीमानंतर (सनाऐवजीही पठण करता येते).", "नबी ﷺ तकबीर आणि किराअत दरम्यान हे पठण करत."),
        "dua_hamdan_kathiran" to DuaText("रुकूनंतर विपुल स्तुती", "हे आमच्या रब! तुझ्यासाठीच स्तुती आहे — विपुल, पवित्र आणि बरकतयुक्त स्तुती.", "रुकूतून उठून 'रब्बना लकल हम्द' सोबत.", "तीसपेक्षा जास्त फरिश्ते हे आधी लिहिण्यासाठी स्पर्धा करत होते."),
        "dua_subbuhun_quddus" to DuaText("सुब्बूहुन कुद्दूस (रुकू आणि सजदा)", "(अल्लाह) अत्यंत पवित्र, अत्यंत पुनीत आहे, फरिश्ते आणि रूह (जिब्रील) यांचा रब.", "रुकू आणि सजद्यात.", "नबी ﷺ रुकू आणि सजद्यात हे पठण करत."),
        "dua_sujood_dhanbi_kullah" to DuaText("सजद्यात: माझी सर्व पापे माफ कर", "हे अल्लाह! माझी सर्व पापे माफ कर — लहान आणि मोठी, पूर्वीची आणि नंतरची, उघड आणि गुप्त.", "सजद्यात.", "सजदा दुआ कबूल होण्याचे ठिकाण आहे."),
        "dua_sujood_ridaka" to DuaText("तुझ्या प्रसन्नतेचा आश्रय", "हे अल्लाह! मी तुझ्या प्रसन्नतेद्वारे तुझ्या नाराजीपासून, तुझ्या क्षमेद्वारे तुझ्या शिक्षेपासून आश्रय मागतो, आणि तुझ्यापासून तुझाच आश्रय मागतो. मी तुझी स्तुती पूर्णपणे करू शकत नाही, तू तसाच आहेस जशी तू स्वतःची स्तुती केलीस.", "सजद्यात — आयशा (र.) यांनी नबी ﷺ यांना हे पठण करताना ऐकले.", "नबी ﷺ यांची सजद्याची दुआ."),
        "dua_tashahhud" to DuaText("तशह्हुद (अत्तहिय्यात)", "सर्व वाचिक, शारीरिक आणि आर्थिक उपासना अल्लाहसाठी आहेत. हे नबी! तुमच्यावर सलाम, अल्लाहची कृपा आणि त्याच्या बरकती असोत. आमच्यावर आणि अल्लाहच्या सदाचारी दासांवर सलाम असो. मी साक्ष देतो की अल्लाहशिवाय कोणी उपास्य नाही, आणि साक्ष देतो की मुहम्मद ﷺ त्याचे दास आणि रसूल आहेत.", "प्रत्येक कादा मध्ये — अब्दुल्लाह बिन मसऊद (र.) यांचे वर्णन (हनफींची प्रथा).", "नबी ﷺ हे कुरआनच्या सूरहप्रमाणे शिकवत."),
        "dua_sajdah_tilawah" to DuaText("सजदा-ए-तिलावत", "माझ्या चेहऱ्याने त्याला सजदा केला ज्याने त्याला निर्माण केले आणि आपल्या शक्ती व सामर्थ्याने त्याचे कान आणि डोळे बनवले.", "सजदा-ए-तिलावतमध्ये.", "नबी ﷺ रात्रीच्या सजदा-ए-तिलावतमध्ये हे पठण करत."),
        "dua_after_witr" to DuaText("वित्रनंतर", "पवित्र आहे तो राजा, अत्यंत पुनीत.", "वित्रच्या सलामनंतर तीन वेळा, तिसऱ्यांदा मोठ्या आवाजात.", "नबी ﷺ वित्रनंतर हे म्हणत."),
        "dua_tahajjud_nur" to DuaText("तहज्जुदची प्रारंभिक दुआ", "हे अल्लाह! तुझ्यासाठीच स्तुती आहे, तू आकाश, पृथ्वी आणि त्यांतील सर्वांचा आधार आहेस. तुझ्यासाठीच स्तुती आहे, तू आकाश, पृथ्वी आणि त्यांतील सर्वांचा प्रकाश आहेस. तुझ्यासाठीच स्तुती आहे, तू सत्य आहेस, तुझे वचन सत्य आहे, तुझी भेट सत्य आहे, तुझे वचन सत्य आहे, जन्नत सत्य आहे, जहन्नम सत्य आहे, नबी सत्य आहेत, मुहम्मद ﷺ सत्य आहेत आणि कयामत सत्य आहे.", "रात्रीची नमाज (तहज्जुद) सुरू करताना (दुआचा प्रारंभिक भाग).", "नबी ﷺ तहज्जुदसाठी उठून हे पठण करत (संपूर्ण दुआ बुखारीत आहे)."),
        "dua_rabba_jibrail" to DuaText("वादग्रस्त बाबतीत मार्गदर्शन", "हे अल्लाह, जिब्रील, मीकाईल आणि इस्राफील यांच्या रब, आकाश व पृथ्वीच्या निर्मात्या, गुप्त आणि उघडाच्या जाणकारा! तू तुझ्या दासांमध्ये त्या गोष्टींचा निर्णय करशील ज्यांत ते मतभेद करत. ज्या सत्यात मतभेद झाला, तुझ्या आदेशाने त्यात मला मार्गदर्शन कर. निश्चितच तू ज्याला इच्छितोस त्याला सरळ मार्ग दाखवतोस.", "तहज्जुदच्या सुरुवातीला — मतभेदाच्या वेळी सत्याचे मार्गदर्शन.", "नबी ﷺ रात्रीची नमाज याच दुआने सुरू करत."),
        "dua_going_to_mosque_nur" to DuaText("मशिदीत जाताना (प्रकाशाची दुआ)", "हे अल्लाह! माझ्या हृदयात प्रकाश कर, माझ्या डोळ्यांत प्रकाश, माझ्या कानांत प्रकाश, माझ्या उजवीकडे प्रकाश, माझ्या डावीकडे प्रकाश, माझ्या वर प्रकाश, माझ्या खाली प्रकाश, माझ्या पुढे प्रकाश, माझ्या मागे प्रकाश, आणि माझ्यासाठी प्रकाश बनव.", "फज्रसाठी मशिदीत जाताना.", "नबी ﷺ नमाजसाठी निघताना हे पठण करत."),
        "dua_waswasa_salah" to DuaText("नमाजमध्ये वसवसा (खिंजब)", "मी धिक्कारलेल्या शैतानापासून अल्लाहचा आश्रय मागतो.", "नमाजमध्ये शैतानी वसवसे आल्यास आश्रय मागून डावीकडे तीन वेळा हलके थुंकावे.", "उस्मान बिन अबिल आस (र.) यांनी हे केले आणि वसवसा निघून गेला."),
        "dua_alimal_ghayb" to DuaText("अदृश्याचा जाणकार", "हे अल्लाह, अदृश्य आणि दृश्याच्या जाणकारा, आकाश व पृथ्वीच्या निर्मात्या, प्रत्येक गोष्टीच्या रब आणि मालका! मी साक्ष देतो की तुझ्याशिवाय कोणी उपास्य नाही. मी माझ्या मनाच्या वाईटापासून, आणि शैतानाच्या वाईटापासून आणि त्याच्या शिर्कपासून तुझा आश्रय मागतो.", "सकाळ, संध्याकाळ आणि झोपण्यापूर्वी — नबी ﷺ यांनी अबू बक्र (र.) यांना शिकवली.", "मन आणि शैतानाच्या वाईटापासून संरक्षण."),
        "dua_fitratil_islam" to DuaText("इस्लामच्या फितरतवर", "आम्ही इस्लामच्या फितरतवर, इखलासच्या कलिम्यावर, आमचे नबी मुहम्मद ﷺ यांच्या दीनवर आणि आमचे पिता इब्राहीम (अ.) यांच्या मिल्लतवर सकाळ केली, जे एकनिष्ठ मुस्लिम होते आणि मुशरिकांपैकी नव्हते.", "सकाळी.", "प्रत्येक सकाळी ईमानचे नूतनीकरण."),
        "dua_amsayna_fitrah" to DuaText("संध्याकाळी इस्लामच्या फितरतवर", "आम्ही इस्लामच्या फितरतवर, इखलासच्या कलिम्यावर, आमचे नबी मुहम्मद ﷺ यांच्या दीनवर आणि आमचे पिता इब्राहीम (अ.) यांच्या मिल्लतवर संध्याकाळ केली, जे एकनिष्ठ मुस्लिम होते आणि मुशरिकांपैकी नव्हते.", "संध्याकाळी.", "प्रत्येक संध्याकाळी ईमानचे नूतनीकरण."),
        "dua_tahleel_10_fajr" to DuaText("फज्र आणि मगरिबनंतर दहा वेळा तहलील", "अल्लाहशिवाय कोणी उपास्य नाही, तो एकटा आहे, त्याला कोणी भागीदार नाही, राज्य आणि स्तुती त्याचीच, तोच जीवन देतो आणि मृत्यू देतो, आणि तो प्रत्येक गोष्टीवर समर्थ आहे.", "फज्र (आणि मगरिब) नंतर, पाय न वळवता आणि न बोलता दहा वेळा.", "दहा पुण्ये, दहा पापे माफ, दहा दर्जे उंच आणि दिवसभर शैतानापासून संरक्षण."),
        "dua_la_hawla_kanz" to DuaText("जन्नतचा खजिना", "अल्लाहशिवाय कोणतीही शक्ती नाही आणि कोणतेही सामर्थ्य नाही.", "प्रत्येक वेळी वारंवार.", "हा जन्नतच्या खजिन्यांपैकी एक खजिना आहे."),
        "dua_four_beloved_words" to DuaText("सर्वात प्रिय चार वाक्ये", "अल्लाह पवित्र आहे, सर्व स्तुती अल्लाहसाठी आहे, अल्लाहशिवाय कोणी उपास्य नाही, आणि अल्लाह सर्वात महान आहे.", "अल्लाहला सर्वात प्रिय वाक्ये.", "नबी ﷺ यांना ही वाक्ये सूर्य ज्यावर उगवतो त्या सर्वांपेक्षा प्रिय आहेत."),
        "dua_two_light_words" to DuaText("जिभेवर हलकी दोन वाक्ये", "अल्लाह पवित्र आहे आणि स्तुती त्याचीच, महान अल्लाह पवित्र आहे.", "जिभेवर हलकी, तराजूत जड.", "रहमानला प्रिय, जिभेवर हलकी आणि तराजूत जड. (बुखारीची शेवटची हदीस)"),
        "dua_ya_dhal_jalal" to DuaText("या जल जलालि वल इक्राम", "हे वैभव आणि सन्मानाच्या मालका!", "दुआमध्ये हे धरून ठेवा — नबी ﷺ यांचा आदेश.", "नबी ﷺ म्हणाले: 'या जल जलालि वल इक्राम' धरून ठेवा."),
        "dua_sleep_wadatu_janbi" to DuaText("तुझ्या नावाने मी कूस ठेवली", "हे माझ्या रब! तुझ्या नावाने मी माझी कूस ठेवली आणि तुझ्याच नावाने उठेन. जर तू माझा आत्मा रोखलास तर त्यावर दया कर, आणि जर सोडलास तर त्याचे असे रक्षण कर जसे तू तुझ्या सदाचारी दासांचे रक्षण करतोस.", "अंथरूण झटकून पडल्यानंतर.", "झोपण्यापूर्वी आत्मा अल्लाहच्या स्वाधीन करणे."),
        "dua_sleep_khalaqta_nafsi" to DuaText("तू माझा आत्मा निर्माण केलास", "हे अल्लाह! तू माझा आत्मा निर्माण केलास आणि तूच त्याला मृत्यू देशील. त्याचे मरणे आणि जगणे तुझ्यासाठीच आहे. जर तू त्याला जिवंत ठेवलेस तर त्याचे रक्षण कर, आणि मृत्यू दिलास तर त्याला क्षमा कर. हे अल्लाह! मी तुझ्याकडे सुरक्षितता मागतो.", "झोपण्यापूर्वी — इब्न उमर (र.) यांचे वर्णन.", "नबी ﷺ यांनी झोपताना हे पठण करण्याचा आदेश दिला."),
        "dua_sleep_atamana" to DuaText("झोपण्यापूर्वी कृतज्ञता", "सर्व स्तुती अल्लाहसाठी ज्याने आम्हाला खाऊ घातले, पाजले, आमची गरज पूर्ण केली आणि आश्रय दिला. असे कितीतरी लोक आहेत ज्यांची गरज पूर्ण करणारा कोणी नाही ना आश्रय देणारा.", "अंथरुणावर जाताना.", "नबी ﷺ अंथरुणावर जाताना हे म्हणत."),
        "dua_sleep_rabbas_samawat" to DuaText("आकाशांच्या रब — आमचे कर्ज फेड", "हे अल्लाह, आकाश, पृथ्वी आणि महान अर्शच्या रब, आमच्या आणि प्रत्येक गोष्टीच्या रब, दाणा आणि बी फोडणाऱ्या, तौरात, इंजील आणि फुरकान उतरवणाऱ्या! मी प्रत्येक त्या गोष्टीच्या वाईटापासून तुझा आश्रय मागतो जिचे कपाळ तुझ्या हाती आहे. हे अल्लाह! तूच पहिला आहेस, तुझ्या आधी काहीही नाही; तूच शेवटचा आहेस, तुझ्यानंतर काहीही नाही; तूच प्रकट आहेस, तुझ्या वर काहीही नाही; तूच गुप्त आहेस, तुझ्यापासून काहीही लपलेले नाही. आमचे कर्ज फेड आणि आम्हाला दारिद्र्यापासून मुक्त कर.", "झोपण्यापूर्वी उजव्या कुशीवर — फातिमा (र.) यांना शिकवली.", "कर्ज आणि तंगीपासून सुटकेची दुआ."),
        "dua_sleep_fear" to DuaText("झोपेत भीती किंवा अस्वस्थता", "मी अल्लाहच्या परिपूर्ण कलिमांचा आश्रय मागतो त्याच्या क्रोध आणि शिक्षेपासून, त्याच्या दासांच्या वाईटापासून, आणि शैतानांच्या वसवशांपासून आणि ते माझ्याजवळ येण्यापासून.", "झोपेत अस्वस्थता किंवा भीती वाटल्यास.", "असे केल्याने ती गोष्ट हानी करणार नाही."),
        "dua_waking_afani" to DuaText("उठल्यावर: त्याने माझा आत्मा परत केला", "सर्व स्तुती अल्लाहसाठी ज्याने माझ्या शरीराला आरोग्य दिले, माझा आत्मा मला परत केला आणि मला त्याचा जिक्र करण्याची परवानगी दिली.", "उठल्यावर.", "नव्या सकाळसाठी कृतज्ञता."),
        "dua_allahu_rabbi" to DuaText("अल्लाह, अल्लाह माझा रब आहे", "अल्लाह, अल्लाह माझा रब आहे, मी त्याच्यासोबत कोणालाही भागीदार करत नाही.", "दुःख किंवा चिंतेच्या वेळी — नबी ﷺ यांनी अस्मा बिन्त उमैस (र.) यांना शिकवली.", "चिंतेच्या वेळी तौहीदचा आधार."),
    )
}
